{
  "conversations": [
    {
      "title": "Ask for a specific place",
      "lines": [
        {
          "speaker": "you",
          "text": "How do I get to the main train station?"
        },
        {
          "speaker": "partner",
          "text": "Take tram number four."
        },
        {
          "speaker": "partner",
          "text": "Get off at the third stop."
        },
        {
          "speaker": "you",
          "text": "Where's the tram stop?"
        },
        {
          "speaker": "partner",
          "text": "It's over there."
        },
        {
          "speaker": "you",
          "text": "Thanks."
        }
      ],
      "vocab": [
        "station",
        "tram",
        "take",
        "get off",
        "third"
      ]
    },
    {
      "title": "Understand basic directions",
      "lines": [
        {
          "speaker": "you",
          "text": "Which bus goes to the museum?"
        },
        {
          "speaker": "partner",
          "text": "Take bus number twelve."
        },
        {
          "speaker": "you",
          "text": "Where's the bus stop?"
        },
        {
          "speaker": "partner",
          "text": "It's across from the bank."
        },
        {
          "speaker": "you",
          "text": "Do I get off at the second stop?"
        },
        {
          "speaker": "partner",
          "text": "Yes, the second stop."
        },
        {
          "speaker": "partner",
          "text": "No, the third stop.",
          "or": true
        },
        {
          "speaker": "you",
          "text": "Thanks."
        }
      ],
      "vocab": [
        "bus",
        "museum",
        "stop",
        "bank",
        "across",
        "get off"
      ]
    },
    {
      "title": "Ask to repeat or slow down",
      "lines": [
        {
          "speaker": "you",
          "text": "Which tram goes to the airport?"
        },
        {
          "speaker": "partner",
          "text": "Tram number six."
        },
        {
          "speaker": "you",
          "text": "Could you repeat that, please?"
        },
        {
          "speaker": "partner",
          "text": "Tram number six."
        },
        {
          "speaker": "you",
          "text": "Could you speak more slowly, please?"
        },
        {
          "speaker": "partner",
          "text": "Take tram number six."
        },
        {
          "speaker": "you",
          "text": "Thanks."
        }
      ],
      "vocab": [
        "repeat",
        "speak",
        "slowly",
        "airport",
        "number"
      ]
    }
  ]
}
